const js0 = `(function(){
document.querySelectorAll('.fi').forEach(item=>{
  item.querySelector('.fi-q').onclick=()=>{
    const on=item.classList.contains('on');
    document.querySelectorAll('.fi').forEach(f=>f.classList.remove('on'));
    if(!on)item.classList.add('on');
  };
});
const hdr=document.getElementById('hdr');
if(hdr)window.addEventListener('scroll',()=>hdr.classList.toggle('up',scrollY>40),{passive:true});
})();`

